        MOUSEMOVE: 'mousemove',
        MOUSEOUT: 'mouseout',
        MOUSEUP: 'mouseup',
        MOUSEWHEEL: 'mousewheel',
        MSPOINTERDOWN: 'MSPointerDown',
        RESIZE: 'resize',
        TOUCHSTART: 'touchstart',
        TOUCHMOVE: 'touchmove',
        TOUCHEND: 'touchend',
