        ['bubbles', false],
        ['cancelable', false],
        ['view', null],
        ['detail', null],
        ['screenX', 0],
        ['screenY', 0],
        ['clientX', 0],
        ['clientY', 0],
        ['ctrlKey', false],
        ['altKey', false],
        ['shiftKey', false],
        ['metaKey', false],
        ['button', 0],
        ['relatedTarget', null],
        // DOM Level 3
        ['buttons', 0],
        // PointerEvent
        ['pointerId', 0],
        ['width', 0],
        ['height', 0],
        ['pressure', 0],
        ['tiltX', 0],
        ['tiltY', 0],
        ['pointerType', ''],
        ['hwTimestamp', 0],
        ['isPrimary', false],
        // event instance
        ['type', ''],
        ['target', null],
        ['currentTarget', null],
        ['which', 0]
