            var imageReplay = replayGroup.getReplay(
                style.getZIndex(), ol.render.ReplayType.IMAGE);
            imageReplay.setImageStyle(imageStyle, replayGroup.addDeclutter(false));
            imageReplay.drawPoint(geometry, feature);
