    goog.require('ol');
    goog.require('ol.Feature');
    goog.require('ol.format.Feature');
    goog.require('ol.format.IGCZ');
    goog.require('ol.format.TextFeature');
    goog.require('ol.geom.GeometryLayout');
    goog.require('ol.geom.LineString');
