        /**
         * @private
         * @type {ol.Extent}
         */
        this.extent_ = extent;

        /**
         * @private
         * @type {boolean}
         */
        this.preemptive_ = preemptive;

        /**
         * @private
         * @type {Array.<string>}
         */
        this.grid_ = null;

        /**
         * @private
         * @type {Array.<string>}
         */
        this.keys_ = null;

        /**
         * @private
         * @type {Object.<string, Object>|undefined}
         */
        this.data_ = null;


